function validate([s]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 20000) return 's needs 1 to 20000 characters.';
  if (!/^[abc]+$/.test(s)) return "s may contain only 'a', 'b' and 'c'.";
  return null;
}

