function generate(rand, size) {
  const pick = (k) => Math.floor(rand() * k);
  const build = (blocks) => {
    // Each stack entry is a started block: 1 after its "a", 2 after its "ab".
    const out = [];
    const open = [];
    let started = 0;
    while (started < blocks || open.length) {
      if (started < blocks && (!open.length || rand() < 0.5)) {
        out.push('a');
        open.push(1);
        started++;
      } else if (open[open.length - 1] === 1) {
        out.push('b');
        open[open.length - 1] = 2;
      } else {
        out.push('c');
        open.pop();
      }
    }
    return out;
  };
  const mutate = (chars) => {
    const i = pick(chars.length);
    const kind = pick(4);
    if (kind === 0) chars[i] = 'abc'[pick(3)];
    else if (kind === 1 && i + 1 < chars.length) [chars[i], chars[i + 1]] = [chars[i + 1], chars[i]];
    else if (kind === 2 && chars.length > 1) chars.splice(i, 1);
    else chars.splice(i, 0, 'abc'[pick(3)]);
    return chars;
  };
  if (size === 'large') {
    const chars = build(3333);
    return [(rand() < 0.5 ? chars : mutate(chars)).join('')];
  }
  if (rand() < 0.25) {
    return [Array.from({ length: 1 + pick(9) }, () => 'abc'[pick(3)]).join('')];
  }
  const chars = build(1 + pick(4));
  return [(rand() < 0.5 ? chars : mutate(chars)).join('')];
}
